metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "de"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "event",
        "text": "Wenn der Wahl-Timer abläuft"
      },
      "body": [
        {
          "id": "b1",
          "kind": "if",
          "text": "Bin ich der Leader?",
          "yes": {
            "id": "r1",
            "body": [
              {
                "id": "b2",
                "kind": "process",
                "text": ""
              }
            ]
          },
          "no": {
            "id": "r2",
            "body": [
              {
                "id": "b3",
                "kind": "process",
                "text": "Kandidat werden"
              },
              {
                "id": "b4",
                "kind": "process",
                "text": "Amtszeit um eins erhöhen"
              },
              {
                "id": "b5",
                "kind": "process",
                "text": "Für mich selbst stimmen\n(Stimmen = 1)"
              },
              {
                "id": "b6",
                "kind": "process",
                "text": "Wahl-Timer auf eine zufällige Zeit zurücksetzen"
              },
              {
                "id": "b7",
                "kind": "process",
                "text": "Wahlanfrage an alle Peers senden\n(Amtszeit, Index und Amtszeit meines letzten Eintrags)"
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "event",
        "text": "Wenn eine Wahlanfrage eintrifft"
      },
      "body": [
        {
          "id": "b8",
          "kind": "if",
          "text": "Amtszeit der Anfrage > meine Amtszeit?",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b9",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b10",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b11",
          "kind": "if",
          "text": "Amtszeit der Anfrage < meine Amtszeit?",
          "yes": {
            "id": "r5",
            "body": [
              {
                "id": "b12",
                "kind": "process",
                "text": "Antworten: abgelehnt"
              }
            ]
          },
          "no": {
            "id": "r6",
            "body": [
              {
                "id": "b13",
                "kind": "if",
                "text": "In dieser Amtszeit noch nicht gewählt\noder schon für diesen Kandidaten?",
                "yes": {
                  "id": "r7",
                  "body": [
                    {
                      "id": "b14",
                      "kind": "if",
                      "text": "Ist das Log des Kandidaten mindestens so aktuell wie meines?",
                      "yes": {
                        "id": "r8",
                        "body": [
                          {
                            "id": "b15",
                            "kind": "process",
                            "text": "Vermerken, dass ich für diesen Kandidaten gestimmt habe"
                          },
                          {
                            "id": "b16",
                            "kind": "process",
                            "text": "Wahl-Timer zurücksetzen"
                          },
                          {
                            "id": "b17",
                            "kind": "process",
                            "text": "Antworten: Stimme erteilt"
                          }
                        ]
                      },
                      "no": {
                        "id": "r9",
                        "body": [
                          {
                            "id": "b18",
                            "kind": "process",
                            "text": "Antworten: abgelehnt"
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r10",
                  "body": [
                    {
                      "id": "b19",
                      "kind": "process",
                      "text": "Antworten: abgelehnt"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "event",
        "text": "Wenn eine Wahlantwort eintrifft"
      },
      "body": [
        {
          "id": "b20",
          "kind": "if",
          "text": "Amtszeit der Antwort > meine Amtszeit?",
          "yes": {
            "id": "r11",
            "body": [
              {
                "id": "b21",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r12",
            "body": [
              {
                "id": "b22",
                "kind": "if",
                "text": "Noch Kandidat und eine Stimme\nfür mich in dieser Amtszeit?",
                "yes": {
                  "id": "r13",
                  "body": [
                    {
                      "id": "b23",
                      "kind": "process",
                      "text": "Stimmen um eins erhöhen"
                    },
                    {
                      "id": "b24",
                      "kind": "if",
                      "text": "Haben die Stimmen die Mehrheit?",
                      "yes": {
                        "id": "r14",
                        "body": [
                          {
                            "id": "b25",
                            "kind": "process",
                            "text": "Leader werden"
                          },
                          {
                            "id": "b26",
                            "kind": "process",
                            "text": "Nächsten Index jedes Peers\nauf meinen letzten Index + 1 setzen"
                          },
                          {
                            "id": "b27",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d8"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r15",
                        "body": [
                          {
                            "id": "b28",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r16",
                  "body": [
                    {
                      "id": "b29",
                      "kind": "process",
                      "text": ""
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d4",
      "head": {
        "kind": "event",
        "text": "Wenn der Heartbeat-Timer abläuft"
      },
      "body": [
        {
          "id": "b30",
          "kind": "if",
          "text": "Bin ich der Leader?",
          "yes": {
            "id": "r17",
            "body": [
              {
                "id": "b31",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d8"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r18",
            "body": [
              {
                "id": "b32",
                "kind": "process",
                "text": ""
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d5",
      "head": {
        "kind": "event",
        "text": "Wenn eine Client-Anfrage eintrifft"
      },
      "body": [
        {
          "id": "b33",
          "kind": "if",
          "text": "Bin ich der Leader?",
          "yes": {
            "id": "r19",
            "body": [
              {
                "id": "b34",
                "kind": "process",
                "text": "Befehl als neuen Eintrag dieser Amtszeit\nan das Log anhängen"
              },
              {
                "id": "b35",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d8"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r20",
            "body": [
              {
                "id": "b36",
                "kind": "process",
                "text": "Dem Client die Adresse des Leaders mitteilen"
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d6",
      "head": {
        "kind": "event",
        "text": "Wenn eine Log-Replikationsanfrage eintrifft"
      },
      "body": [
        {
          "id": "b37",
          "kind": "if",
          "text": "Amtszeit der Anfrage < meine Amtszeit?",
          "yes": {
            "id": "r21",
            "body": [
              {
                "id": "b38",
                "kind": "process",
                "text": "Antworten: fehlgeschlagen\n(mit meiner Amtszeit)"
              }
            ]
          },
          "no": {
            "id": "r22",
            "body": [
              {
                "id": "b39",
                "kind": "if",
                "text": "Amtszeit der Anfrage > meine Amtszeit\noder bin ich Kandidat?",
                "yes": {
                  "id": "r23",
                  "body": [
                    {
                      "id": "b40",
                      "kind": "call",
                      "target": {
                        "kind": "local",
                        "diagram": "d10"
                      },
                      "args": "",
                      "result": ""
                    }
                  ]
                },
                "no": {
                  "id": "r24",
                  "body": [
                    {
                      "id": "b41",
                      "kind": "process",
                      "text": ""
                    }
                  ]
                }
              },
              {
                "id": "b42",
                "kind": "process",
                "text": "Wahl-Timer zurücksetzen"
              },
              {
                "id": "b43",
                "kind": "if",
                "text": "Passen Index und Amtszeit des vorigen Eintrags zu meinem Log?",
                "yes": {
                  "id": "r25",
                  "body": [
                    {
                      "id": "b44",
                      "kind": "process",
                      "text": "Meine Einträge ab dem ersten Konflikt löschen"
                    },
                    {
                      "id": "b45",
                      "kind": "process",
                      "text": "Neue Einträge an das Log anhängen"
                    },
                    {
                      "id": "b46",
                      "kind": "if",
                      "text": "Commit-Index des Leaders > meiner?",
                      "yes": {
                        "id": "r26",
                        "body": [
                          {
                            "id": "b47",
                            "kind": "process",
                            "text": "Meinen Commit-Index erhöhen\n(auf den kleineren Wert von Commit-Index\ndes Leaders und meinem letzten Index)"
                          },
                          {
                            "id": "b48",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d9"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r27",
                        "body": [
                          {
                            "id": "b49",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    },
                    {
                      "id": "b50",
                      "kind": "process",
                      "text": "Antworten: erfolgreich"
                    }
                  ]
                },
                "no": {
                  "id": "r28",
                  "body": [
                    {
                      "id": "b51",
                      "kind": "process",
                      "text": "Antworten: fehlgeschlagen"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d7",
      "head": {
        "kind": "event",
        "text": "Wenn eine Log-Replikationsantwort eintrifft"
      },
      "body": [
        {
          "id": "b52",
          "kind": "if",
          "text": "Amtszeit der Antwort > meine Amtszeit?",
          "yes": {
            "id": "r29",
            "body": [
              {
                "id": "b53",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r30",
            "body": [
              {
                "id": "b54",
                "kind": "if",
                "text": "Erfolgreich?",
                "yes": {
                  "id": "r31",
                  "body": [
                    {
                      "id": "b55",
                      "kind": "process",
                      "text": "Match-Index und nächsten Index des Peers erhöhen"
                    },
                    {
                      "id": "b56",
                      "kind": "if",
                      "text": "Hält eine Mehrheit einen noch nicht\nfestgeschriebenen Eintrag dieser Amtszeit?",
                      "yes": {
                        "id": "r32",
                        "body": [
                          {
                            "id": "b57",
                            "kind": "process",
                            "text": "Commit-Index bis dorthin erhöhen"
                          },
                          {
                            "id": "b58",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d9"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r33",
                        "body": [
                          {
                            "id": "b59",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r34",
                  "body": [
                    {
                      "id": "b60",
                      "kind": "process",
                      "text": "Nächsten Index des Peers um eins verringern\n(beim nächsten Heartbeat wird erneut gesendet)"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d8",
      "head": {
        "kind": "method",
        "text": "Log an alle Peers senden"
      },
      "body": [
        {
          "id": "b61",
          "kind": "while",
          "text": "Solange noch ein Peer übrig ist",
          "body": [
            {
              "id": "b62",
              "kind": "process",
              "text": "Einträge für diesen Peer auswählen\n(von seinem nächsten Index bis zum Ende,\nbeim Heartbeat keine)"
            },
            {
              "id": "b63",
              "kind": "process",
              "text": "Log-Replikationsanfrage senden\n(Amtszeit, vorheriger Index und Amtszeit,\nEinträge, Commit-Index)"
            }
          ]
        }
      ]
    },
    {
      "id": "d9",
      "head": {
        "kind": "method",
        "text": "Festgeschriebene Einträge auf die Zustandsmaschine anwenden"
      },
      "body": [
        {
          "id": "b64",
          "kind": "while",
          "text": "angewandter Index < Commit-Index",
          "body": [
            {
              "id": "b65",
              "kind": "process",
              "text": "Angewandten Index um eins erhöhen"
            },
            {
              "id": "b66",
              "kind": "process",
              "text": "Befehl dieses Eintrags auf die Zustandsmaschine anwenden"
            },
            {
              "id": "b67",
              "kind": "if",
              "text": "Bin ich der Leader?",
              "yes": {
                "id": "r35",
                "body": [
                  {
                    "id": "b68",
                    "kind": "process",
                    "text": "Dem Client mit dem Ergebnis antworten"
                  }
                ]
              },
              "no": {
                "id": "r36",
                "body": [
                  {
                    "id": "b69",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            }
          ]
        }
      ]
    },
    {
      "id": "d10",
      "head": {
        "kind": "method",
        "text": "Zum Follower zurückstufen"
      },
      "body": [
        {
          "id": "b70",
          "kind": "if",
          "text": "Amtszeit der Gegenseite > meine Amtszeit?",
          "yes": {
            "id": "r37",
            "body": [
              {
                "id": "b71",
                "kind": "process",
                "text": "Meine Amtszeit auf die der Gegenseite anheben"
              },
              {
                "id": "b72",
                "kind": "process",
                "text": "Meine Stimme für diese Amtszeit löschen"
              }
            ]
          },
          "no": {
            "id": "r38",
            "body": [
              {
                "id": "b73",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b74",
          "kind": "process",
          "text": "Follower werden"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
